@code {
    private List<TaskItem> allTasks = new();
    private string searchText = "";
    private bool isLoading = true;
    private string? errorMessage;

    private static readonly string[] StatusOrder = { "To Do", "In Progress", "Done" };

    protected override async Task OnInitializedAsync()
    {
        try
        {
            allTasks = await TaskService.GetAllTasksAsync();
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to load tasks: {ex.Message}";
        }
        finally
        {
            isLoading = false;
        }
    }

    private List<TaskItem> GetFilteredTasks(string status)
    {
        var tasks = allTasks.Where(t => t.Status == status);
        if (!string.IsNullOrWhiteSpace(searchText))
        {
            tasks = tasks.Where(t => t.Title.Contains(searchText, StringComparison.OrdinalIgnoreCase));
        }
        return tasks.ToList();
    }

    private async Task MoveLeft(TaskItem task)
    {
        var currentIndex = Array.IndexOf(StatusOrder, task.Status);
        if (currentIndex <= 0) return;

        var newStatus = StatusOrder[currentIndex - 1];
        await TaskService.UpdateTaskStatusAsync(task.Id, newStatus);
        UpdateLocalTaskStatus(task, newStatus);
    }

    private async Task MoveRight(TaskItem task)
    {
        var currentIndex = Array.IndexOf(StatusOrder, task.Status);
        if (currentIndex >= StatusOrder.Length - 1) return;

        var newStatus = StatusOrder[currentIndex + 1];
        await TaskService.UpdateTaskStatusAsync(task.Id, newStatus);
        UpdateLocalTaskStatus(task, newStatus);
    }

    private void UpdateLocalTaskStatus(TaskItem task, string newStatus)
    {
        var index = allTasks.FindIndex(t => t.Id == task.Id);
        if (index >= 0)
        {
            allTasks[index] = task with { Status = newStatus };
        }
    }

    private async Task HandleTaskCreated(AddTaskForm.NewTaskModel model)
    {
        var created = await TaskService.CreateTaskAsync(model.Title, model.Assignee, model.Priority, model.DueDate);
        allTasks.Add(created with { Status = model.Status });
    }
}

