.board-stats {
    display: flex;
    gap: 1.5rem;
    padding: 1rem;
    background: #f8f9fa;
    border-radius: 8px;
    margin-bottom: 1rem;
    flex-wrap: wrap;
}

.stat {
    font-weight: 600;
}

.stat-overdue {
    color: #dc3545;
}

.board-search {
    margin-bottom: 1rem;
}

.board-search input {
    width: 100%;
    padding: 0.5rem 1rem;
    border: 1px solid #dee2e6;
    border-radius: 6px;
    font-size: 1rem;
}

.board-columns {
    display: flex;
    gap: 1rem;
    align-items: flex-start;
}

::deep .board-column {
    flex: 1;
    background: #f1f3f5;
    border-radius: 8px;
    padding: 1rem;
    min-width: 250px;
}

::deep .column-header h3 {
    margin: 0 0 0.75rem 0;
    font-size: 1.1rem;
}

::deep .task-card {
    background: #fff;
    border: 1px solid #dee2e6;
    border-radius: 6px;
    padding: 0.75rem;
    margin-bottom: 0.5rem;
}

::deep .task-card h4 {
    margin: 0 0 0.25rem 0;
    font-size: 0.95rem;
}

::deep .task-card .assignee {
    margin: 0 0 0.25rem 0;
    font-size: 0.85rem;
    color: #6c757d;
}

::deep .priority-badge {
    display: inline-block;
    padding: 0.15rem 0.5rem;
    border-radius: 4px;
    font-size: 0.75rem;
